{
  "lesson_summary": "Today's lesson plans to teach children how to count up to 9999 and recognise the place value of each digit in 4-digit numbers. It will demonstrate building the number 9999 using cubes, flats, rods, and dots, and then writing its expanded form as 9000 + 900 + 90 + 9. The lesson will also address the misconception that a digit's value is determined only by the digit itself, rather than its position.",
  "lesson_summary_short": "Today's lesson plans to teach counting up to 9999 and recognising the place value of each digit, using 9999 as an example.",
  "checks_summary": "This quiz checks whether the class can count 4-digit numbers and identify the place value of digits in numbers like 2015.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "Which of these is a 4-digit number?",
      "options": [
        "9999",
        "999",
        "10000"
      ],
      "correct_index": 0,
      "explanation": "A 4-digit number is a number that has four digits. 9999 has four digits.",
      "selected_because": "The lesson's main example of a 4-digit number.",
      "distractor_misconceptions": {
        "1": "Confuses 3-digit with 4-digit numbers.",
        "2": "Confuses 4-digit with 5-digit numbers."
      },
      "option_feedback": {
        "correct": "That's right! 9999 is the largest 4-digit number, as discussed in class.",
        "wrong": {
          "1": "This number has only three digits. Remember, a 4-digit number has four digits, like 9999.",
          "2": "This number has five digits. A 4-digit number has four digits, like 9999."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "What number do these blocks show?",
      "options": [
        "9999",
        "999",
        "9000"
      ],
      "correct_index": 0,
      "explanation": "The blocks show 9 thousands blocks, 9 hundreds flats, 9 tens rods, and 9 ones cubes, which together make 9999.",
      "selected_because": "The worked example of building 9999 with blocks.",
      "distractor_misconceptions": {
        "1": "Counts only hundreds, tens, and ones, ignoring thousands.",
        "2": "Counts only thousands, ignoring hundreds, tens, and ones."
      },
      "option_feedback": {
        "correct": "Excellent! You correctly identified 9 thousands, 9 hundreds, 9 tens, and 9 ones, which is 9999.",
        "wrong": {
          "1": "Look closely at all the blocks. There are thousands blocks too, not just hundreds, tens, and ones. The picture shows 9999.",
          "2": "You counted the thousands correctly, but don't forget the hundreds, tens, and ones blocks. The picture shows 9999."
        }
      },
      "figure": {
        "type": "base_ten",
        "model": "blocks",
        "thousands": 9,
        "hundreds": 9,
        "tens": 9,
        "ones": 9
      },
      "figure_role": "read_off"
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "In the number 2015, what is the 'place value' of the digit 1?",
      "options": [
        "Tens",
        "Ones",
        "Hundreds"
      ],
      "correct_index": 0,
      "explanation": "In 2015, the digit 1 is in the tens place, so its place value is Tens.",
      "selected_because": "The practice example of 2015 and identifying place value.",
      "distractor_misconceptions": {
        "1": "Confuses tens place with ones place.",
        "2": "Confuses tens place with hundreds place."
      },
      "option_feedback": {
        "correct": "You got it! The digit 1 in 2015 is in the Tens place.",
        "wrong": {
          "1": "Remember the order of place values: Ones, Tens, Hundreds, Thousands. The 1 in 2015 is not in the Ones place, it's in the Tens place.",
          "2": "The 0 is in the Hundreds place in 2015. The 1 is in the Tens place."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "apply",
      "question": "The number 1985 has an 8. What is the value of this 8?",
      "options": [
        "80",
        "8",
        "800"
      ],
      "correct_index": 0,
      "explanation": "The digit 8 in 1985 is in the tens place, so its value is 8 multiplied by 10, which is 80.",
      "selected_because": "The misconception example of 1985 and the value of 8.",
      "distractor_misconceptions": {
        "1": "Reads the digit at face value, ignoring its place.",
        "2": "Confuses tens place with hundreds place."
      },
      "option_feedback": {
        "correct": "That's correct! The 8 in 1985 is in the Tens place, so its value is 80.",
        "wrong": {
          "1": "The value of a digit depends on its place. The 8 is in the Tens place, so its value is 80, not just 8.",
          "2": "The 8 in 1985 is in the Tens place, not the Hundreds place. Its value is 80."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which place value is ten times larger than the Tens place?",
      "options": [
        "Hundreds",
        "Ones",
        "Thousands"
      ],
      "correct_index": 0,
      "explanation": "Each place is ten times the one on its right. So, the Hundreds place is ten times larger than the Tens place.",
      "selected_because": "The lesson's ending point about place value relationships.",
      "distractor_misconceptions": {
        "1": "Confuses smaller place with larger place.",
        "2": "Confuses hundreds with thousands."
      },
      "option_feedback": {
        "correct": "Exactly! The Hundreds place is ten times larger than the Tens place.",
        "wrong": {
          "1": "The Ones place is smaller than the Tens place. Remember, each place is ten times larger than the one to its right.",
          "2": "The Thousands place is ten times larger than the Hundreds place. The Hundreds place is ten times larger than the Tens place."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S1",
      "level": "apply",
      "question": "If you count on one from 2015, which place value changes first?",
      "options": [
        "Ones",
        "Tens",
        "Hundreds"
      ],
      "correct_index": 0,
      "explanation": "When counting on by one, the Ones place is always the first to change.",
      "selected_because": "The lesson's ending point about counting on and place value changes.",
      "distractor_misconceptions": {
        "1": "Believes the tens place changes first when counting by one.",
        "2": "Believes the hundreds place changes first when counting by one."
      },
      "option_feedback": {
        "correct": "That's right! When you count on by one, the Ones place changes first.",
        "wrong": {
          "1": "Counting on by one changes the Ones place first, not the Tens place. Think about 1, 2, 3...",
          "2": "The Hundreds place changes much later. When counting by one, the Ones place changes first."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "What is the expanded form of 9999?",
      "options": [
        "$9000 + 900 + 90 + 9$",
        "$9 + 9 + 9 + 9$",
        "$900 + 90 + 9$"
      ],
      "correct_index": 0,
      "explanation": "The expanded form shows the value of each digit added together. For 9999, it is 9 thousands, 9 hundreds, 9 tens, and 9 ones.",
      "selected_because": "The worked example of writing 9999 in expanded form.",
      "distractor_misconceptions": {
        "1": "Adds the face value of digits instead of their place value.",
        "2": "Omits the thousands place in the expanded form."
      },
      "option_feedback": {
        "correct": "Excellent! $9000 + 900 + 90 + 9$ is the correct expanded form for 9999.",
        "wrong": {
          "1": "This is adding the digits themselves, not their values based on their place. Remember, the 9 in the thousands place is worth 9000. The correct expanded form is $9000 + 900 + 90 + 9$.",
          "2": "You missed the thousands place. 9999 has a 9 in the thousands place, so its expanded form starts with 9000. The correct expanded form is $9000 + 900 + 90 + 9$."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "How many ones are there in one rod?",
      "options": [
        "10",
        "1",
        "100"
      ],
      "correct_index": 0,
      "explanation": "As shown in class, one rod is made up of 10 single ones.",
      "selected_because": "The teacher's explanation of how a rod represents 10 ones to fix a misconception.",
      "distractor_misconceptions": {
        "1": "Confuses a rod with a single unit.",
        "2": "Confuses a rod with a flat (hundreds)."
      },
      "option_feedback": {
        "correct": "You're right! One rod is equal to 10 ones, as we saw with the blocks.",
        "wrong": {
          "1": "A rod is not just one single unit. Remember, a rod is made up of 10 ones.",
          "2": "A flat is 100 ones. A rod is 10 ones."
        }
      },
      "figure": {
        "type": "base_ten",
        "model": "blocks",
        "tens": 1,
        "ones": 10
      },
      "figure_role": "model"
    }
  ]
}
